"use client";
import React, { useEffect, useState, useCallback } from "react";
import { useParams, useRouter } from "next/navigation";
import {
  ArrowLeft, ExternalLink, CheckCircle, XCircle, Clock,
  Archive, Globe, Calendar, AlertTriangle, Shield, FileText,
  Train, MapPin, Loader2, Save, ChevronDown, ChevronUp,
  Newspaper, Eye, EyeOff, RotateCcw, History, HelpCircle,
  Info, Sparkles, CheckCircle2, ListChecks, Layers, Tag, Link2,
  Plus, Trash2
} from "lucide-react";
import { fetchWithAuth } from "@/lib/fetchWithAuth";
import { getApiBaseUrl } from "@/lib/api";
import SafeMarkdown from "@/components/news/SafeMarkdown";

// ─── Types ────────────────────────────────────────────────────────────────────
interface Article {
  id: string;
  title: string;
  summary: string;
  content?: string | null;
  key_takeaways: string[];
  passenger_advice: string | null;
  faq: Array<{ question: string; answer: string }> | null;
  source_name: string;
  source_url: string;
  source_tier: string;
  category: string;
  status: string;
  ai_confidence: string | null;
  rejection_reason: string | null;
  seo_title: string | null;
  meta_description: string | null;
  slug: string | null;
  affected_trains: string[];
  affected_stations: string[];
  published_at: string;
  updated_at: string;
  scheduled_at: string | null;
  admin_reviewed_by: string | null;
  admin_reviewed_at: string | null;
  audit_history: AuditEntry[];
}

interface AuditEntry {
  id: string;
  admin_id: string;
  admin_email: string;
  action: string;
  details: { previous_status: string; new_status: string; reason?: string };
  timestamp: string;
}

// ─── Rejection Reasons ────────────────────────────────────────────────────────
const REJECTION_REASONS = [
  { value: "UNSUPPORTED_CLAIM", label: "Unsupported Claim" },
  { value: "LOW_CONFIDENCE",    label: "Low AI Confidence" },
  { value: "DUPLICATE",         label: "Duplicate Article" },
  { value: "SOURCE_UNTRUSTED",  label: "Source Not Trusted" },
  { value: "OUTDATED",          label: "Outdated Information" },
  { value: "INCORRECT",         label: "Incorrect Facts" },
  { value: "OFF_TOPIC",         label: "Off Topic" },
  { value: "OTHER",             label: "Other" },
];

const STATUS_BADGE: Record<string, { label: string; color: string }> = {
  REVIEW_REQUIRED: { label: "Review Required", color: "bg-orange-500/15 text-orange-400 border-orange-500/30" },
  AI_DRAFTED:      { label: "AI Draft",         color: "bg-indigo-500/15 text-indigo-400 border-indigo-500/30" },
  APPROVED:        { label: "Approved",          color: "bg-emerald-500/15 text-emerald-400 border-emerald-500/30" },
  SCHEDULED:       { label: "Scheduled",         color: "bg-cyan-500/15 text-cyan-400 border-cyan-500/30" },
  PUBLISHED:       { label: "Published",         color: "bg-green-500/15 text-green-400 border-green-500/30" },
  UNPUBLISHED:     { label: "Unpublished",       color: "bg-yellow-500/15 text-yellow-400 border-yellow-500/30" },
  REJECTED:        { label: "Rejected",          color: "bg-red-500/15 text-red-400 border-red-500/30" },
  ARCHIVED:        { label: "Archived",          color: "bg-slate-500/15 text-slate-400 border-slate-500/30" },
};

const TIER_LABEL: Record<string, string> = {
  TIER_1_OFFICIAL: "Tier 1 — Official",
  TIER_2_GOVERNMENT: "Tier 2 — Government",
  TIER_3_RECOGNIZED_MEDIA: "Tier 3 — Recognized Media",
};

const CONFIDENCE_STYLE: Record<string, string> = {
  HIGH:   "text-emerald-400 bg-emerald-400/10 border-emerald-400/20",
  MEDIUM: "text-amber-400 bg-amber-400/10 border-amber-400/20",
  LOW:    "text-red-400 bg-red-400/10 border-red-400/20",
};

// ─── API base ─────────────────────────────────────────────────────────────────
const API = getApiBaseUrl(process.env.NEXT_PUBLIC_API_URL || "").replace(/\/api$/, "");

// ─── Section ─────────────────────────────────────────────────────────────────
function Section({ title, icon, children, defaultOpen = true }: {
  title: string; icon: React.ReactNode; children: React.ReactNode; defaultOpen?: boolean;
}) {
  const [open, setOpen] = useState(defaultOpen);
  return (
    <div className="bg-card border border-subtle rounded-xl overflow-hidden">
      <button
        onClick={() => setOpen(!open)}
        className="w-full flex items-center justify-between px-5 py-4 hover:bg-input/50 transition"
      >
        <div className="flex items-center gap-2.5 text-sm font-bold text-main">
          {icon} {title}
        </div>
        {open ? <ChevronUp size={16} className="text-muted" /> : <ChevronDown size={16} className="text-muted" />}
      </button>
      {open && <div className="px-5 pb-5 border-t border-subtle">{children}</div>}
    </div>
  );
}

// ─── Editable field ───────────────────────────────────────────────────────────
function EditableField({ label, value, onChange, multiline = false, disabled = false, id, rows = 4 }: {
  label: string; value: string; onChange: (v: string) => void;
  multiline?: boolean; disabled?: boolean; id: string; rows?: number;
}) {
  return (
    <div className="space-y-1.5">
      <label htmlFor={id} className="text-[11px] font-semibold text-muted uppercase tracking-wider">{label}</label>
      {multiline ? (
        <textarea
          id={id}
          value={value}
          onChange={e => onChange(e.target.value)}
          disabled={disabled}
          rows={rows}
          className="w-full bg-input border border-subtle rounded-lg px-3 py-2.5 text-sm text-main resize-none outline-none focus:border-primary/60 disabled:opacity-50 transition"
        />
      ) : (
        <input
          id={id}
          value={value}
          onChange={e => onChange(e.target.value)}
          disabled={disabled}
          className="w-full bg-input border border-subtle rounded-lg px-3 py-2.5 text-sm text-main outline-none focus:border-primary/60 disabled:opacity-50 transition"
        />
      )}
    </div>
  );
}

// ─── Main Page ────────────────────────────────────────────────────────────────
export default function NewsReviewPage() {
  const params = useParams<{ id: string }>();
  const router = useRouter();
  const articleId = params.id;

  const [article, setArticle] = useState<Article | null>(null);
  const [loading, setLoading] = useState(true);
  const [actionLoading, setActionLoading] = useState<string | null>(null);
  const [toast, setToast] = useState<{ msg: string; type: "success" | "error" | "info" } | null>(null);

  // Approval dialog
  const [showApproveDialog, setShowApproveDialog] = useState(false);
  const [approveChecks, setApproveChecks] = useState({
    sourceVerified: false,
    confidenceReviewed: false,
    contentAccurate: false,
    entitiesValid: false,
  });

  // Rejection dialog
  const [showRejectDialog, setShowRejectDialog] = useState(false);
  const [rejectReason, setRejectReason] = useState("OTHER");
  const [rejectNote, setRejectNote] = useState("");

  // Schedule dialog
  const [showScheduleDialog, setShowScheduleDialog] = useState(false);
  const [scheduleAt, setScheduleAt] = useState("");

  // Draft edit state
  const [edits, setEdits] = useState<Record<string, any>>({});
  const [hasDraftChanges, setHasDraftChanges] = useState(false);
  const [savingDraft, setSavingDraft] = useState(false);
  const [contentTab, setContentTab] = useState<"edit" | "preview">("edit");

  const showToast = (msg: string, type: "success" | "error" | "info") => {
    setToast({ msg, type });
    setTimeout(() => setToast(null), 3500);
  };

  const getHeaders = (): Record<string, string> => {
    if (typeof window === "undefined") return {};
    const token = localStorage.getItem("accessToken");
    return token ? { Authorization: `Bearer ${token}` } : {};
  };

  const fetchArticle = useCallback(async () => {
    setLoading(true);
    try {
      const res = await fetchWithAuth(`${API}/api/admin/news/${articleId}`, { headers: getHeaders() });
      const json = await res.json();
      if (json.success) {
        setArticle(json.data);
        setEdits({
          title: json.data.title || "",
          summary: json.data.summary || "",
          content: json.data.content || "",
          key_takeaways: (json.data.key_takeaways || []).join("\n"),
          passenger_advice: json.data.passenger_advice || "",
          seo_title: json.data.seo_title || "",
          meta_description: json.data.meta_description || "",
          slug: json.data.slug || "",
          category: json.data.category || "",
          faq: Array.isArray(json.data.faq) ? json.data.faq : [],
        });
        setHasDraftChanges(false);
      } else {
        showToast(json.error || "Failed to load article", "error");
      }
    } catch {
      showToast("Network error", "error");
    } finally {
      setLoading(false);
    }
  }, [articleId]);

  useEffect(() => { fetchArticle(); }, [fetchArticle]);

  const updateEdit = (field: string, value: string) => {
    setEdits(prev => ({ ...prev, [field]: value }));
    setHasDraftChanges(true);
  };

  const updateFaq = (index: number, field: "question" | "answer", val: string) => {
    const list = Array.isArray(edits.faq) ? [...edits.faq] : [];
    if (!list[index]) list[index] = { question: "", answer: "" };
    list[index] = { ...list[index], [field]: val };
    setEdits(prev => ({ ...prev, faq: list }));
    setHasDraftChanges(true);
  };

  const addFaq = () => {
    const list = Array.isArray(edits.faq) ? [...edits.faq] : [];
    list.push({ question: "", answer: "" });
    setEdits(prev => ({ ...prev, faq: list }));
    setHasDraftChanges(true);
  };

  const removeFaq = (index: number) => {
    const list = Array.isArray(edits.faq) ? [...edits.faq] : [];
    list.splice(index, 1);
    setEdits(prev => ({ ...prev, faq: list }));
    setHasDraftChanges(true);
  };

  const saveDraft = async () => {
    if (!hasDraftChanges) return;
    setSavingDraft(true);
    try {
      let cleanFaq: Array<{ question: string; answer: string }> | null = null;
      if (Array.isArray(edits.faq) && edits.faq.length > 0) {
        const valid = edits.faq
          .filter((item: any) => item && typeof item.question === "string" && typeof item.answer === "string")
          .map((item: any) => ({ question: item.question.trim(), answer: item.answer.trim() }))
          .filter((item: any) => item.question && item.answer);
        cleanFaq = valid.length > 0 ? valid : null;
      }

      const payload = {
        ...edits,
        content: typeof edits.content === "string" && edits.content.trim() ? edits.content : null,
        passenger_advice: typeof edits.passenger_advice === "string" && edits.passenger_advice.trim() ? edits.passenger_advice : null,
        faq: cleanFaq,
        key_takeaways: typeof edits.key_takeaways === "string"
          ? edits.key_takeaways.split("\n").filter(Boolean)
          : edits.key_takeaways,
      };

      const res = await fetchWithAuth(`${API}/api/admin/news/${articleId}/draft`, {
        method: "PATCH",
        headers: { ...getHeaders(), "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });
      const json = await res.json();
      if (json.success) {
        showToast("Draft saved ✓", "success");
        setHasDraftChanges(false);
      } else {
        showToast(json.error || "Save failed", "error");
      }
    } catch {
      showToast("Network error", "error");
    } finally {
      setSavingDraft(false);
    }
  };

  const handleApprove = async () => {
    const allChecked = Object.values(approveChecks).every(Boolean);
    if (!allChecked) {
      showToast("All pre-approval checks must be completed.", "error");
      return;
    }
    setActionLoading("approve");
    try {
      const res = await fetchWithAuth(`${API}/api/admin/news/${articleId}/approve`, {
        method: "POST",
        headers: { ...getHeaders(), "Content-Type": "application/json" },
        body: JSON.stringify({ attestation: "I verified the source and approve this article." }),
      });
      const json = await res.json();
      if (json.success) {
        showToast("Article approved ✓", "success");
        setShowApproveDialog(false);
        fetchArticle();
      } else {
        showToast(json.error || "Approval failed", "error");
      }
    } catch {
      showToast("Network error", "error");
    } finally {
      setActionLoading(null);
    }
  };

  const handleReject = async () => {
    setActionLoading("reject");
    try {
      const res = await fetchWithAuth(`${API}/api/admin/news/${articleId}/reject`, {
        method: "POST",
        headers: { ...getHeaders(), "Content-Type": "application/json" },
        body: JSON.stringify({ reason: rejectReason, note: rejectNote }),
      });
      const json = await res.json();
      if (json.success) {
        showToast("Article rejected", "success");
        setShowRejectDialog(false);
        fetchArticle();
      } else {
        showToast(json.error || "Rejection failed", "error");
      }
    } catch {
      showToast("Network error", "error");
    } finally {
      setActionLoading(null);
    }
  };

  const handleSchedule = async () => {
    if (!scheduleAt) { showToast("Please pick a date and time.", "error"); return; }
    setActionLoading("schedule");
    try {
      const res = await fetchWithAuth(`${API}/api/admin/news/${articleId}/schedule`, {
        method: "POST",
        headers: { ...getHeaders(), "Content-Type": "application/json" },
        body: JSON.stringify({ scheduled_at: new Date(scheduleAt).toISOString() }),
      });
      const json = await res.json();
      if (json.success) {
        showToast("Article scheduled ✓", "success");
        setShowScheduleDialog(false);
        fetchArticle();
      } else {
        showToast(json.error || "Scheduling failed", "error");
      }
    } catch {
      showToast("Network error", "error");
    } finally {
      setActionLoading(null);
    }
  };

  const quickAction = async (action: "publish" | "unpublish" | "archive" | "restore") => {
    setActionLoading(action);
    try {
      const res = await fetchWithAuth(`${API}/api/admin/news/${articleId}/${action}`, {
        method: "POST",
        headers: { ...getHeaders(), "Content-Type": "application/json" },
      });
      const json = await res.json();
      if (json.success) {
        showToast(action === "restore" ? "Article restored to draft ✓" : `Article ${action}ed ✓`, "success");
        fetchArticle();
      } else {
        showToast(json.error || `${action} failed`, "error");
      }
    } catch {
      showToast("Network error", "error");
    } finally {
      setActionLoading(null);
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-body flex items-center justify-center">
        <Loader2 className="animate-spin text-primary" size={36} />
      </div>
    );
  }

  if (!article) {
    return (
      <div className="min-h-screen bg-body flex flex-col items-center justify-center gap-4">
        <Newspaper size={48} className="text-muted opacity-40" />
        <p className="text-muted">Article not found.</p>
        <button onClick={() => router.back()} className="text-primary text-sm hover:underline">← Go back</button>
      </div>
    );
  }

  const statusCfg = STATUS_BADGE[article.status] || { label: article.status, color: "bg-muted/10 text-muted border-subtle" };
  const canApprove = ["AI_DRAFTED", "REVIEW_REQUIRED"].includes(article.status);
  const canReject = ["AI_DRAFTED", "REVIEW_REQUIRED", "APPROVED"].includes(article.status);
  const canSchedule = article.status === "APPROVED";
  const canPublish = ["APPROVED", "SCHEDULED"].includes(article.status);
  const canUnpublish = article.status === "PUBLISHED";
  const canArchive = !["ARCHIVED"].includes(article.status);
  const canUnarchive = article.status === "ARCHIVED";
  const canEdit = !["ARCHIVED", "PUBLISHED"].includes(article.status);

  const allApproveChecksPass = Object.values(approveChecks).every(Boolean);

  const currentContent = typeof edits.content === "string" ? edits.content : (article.content || "");
  const contentWordCount = currentContent.trim()
    ? currentContent.trim().split(/\s+/).filter(Boolean).length
    : 0;

  return (
    <div className="min-h-screen bg-body">
      {/* Toast */}
      {toast && (
        <div className={`fixed top-5 right-5 z-50 flex items-center gap-2.5 px-4 py-3 rounded-xl border shadow-xl text-sm font-medium transition-all ${
          toast.type === "success" ? "bg-emerald-500/15 border-emerald-500/30 text-emerald-400" :
          toast.type === "error"   ? "bg-red-500/15 border-red-500/30 text-red-400" :
                                    "bg-blue-500/15 border-blue-500/30 text-blue-400"
        }`}>
          {toast.type === "success" ? <CheckCircle size={14} /> : toast.type === "error" ? <XCircle size={14} /> : <AlertTriangle size={14} />}
          {toast.msg}
        </div>
      )}

      {/* Header */}
      <div className="sticky top-0 z-30 bg-body/90 backdrop-blur border-b border-subtle">
        <div className="max-w-[1440px] mx-auto px-6 py-4 flex flex-wrap items-center justify-between gap-4">
          <div className="flex items-center gap-3">
            <button
              id="news-review-back"
              onClick={() => router.push("/admin?tab=news")}
              className="flex items-center gap-1.5 text-muted hover:text-main text-sm transition"
            >
              <ArrowLeft size={15} /> Back to News CMS
            </button>
            <span className="text-subtle">·</span>
            <span className={`px-2.5 py-1 rounded-full text-xs font-bold border ${statusCfg.color}`}>
              {statusCfg.label}
            </span>
            {article.ai_confidence && (
              <span className={`px-2.5 py-1 rounded-full text-xs font-bold border ${CONFIDENCE_STYLE[article.ai_confidence] || ""}`}>
                AI: {article.ai_confidence}
              </span>
            )}
          </div>

          {/* Actions */}
          <div className="flex items-center gap-2 flex-wrap">
            {hasDraftChanges && canEdit && (
              <button
                id="news-save-draft"
                onClick={saveDraft}
                disabled={savingDraft}
                className="flex items-center gap-1.5 px-3 py-2 text-xs font-bold bg-primary/10 border border-primary/30 hover:bg-primary/20 text-primary rounded-lg transition"
              >
                {savingDraft ? <Loader2 size={12} className="animate-spin" /> : <Save size={12} />} Save Draft
              </button>
            )}
            {canApprove && (
              <button id="news-approve-btn" onClick={() => setShowApproveDialog(true)}
                className="flex items-center gap-1.5 px-3 py-2 text-xs font-bold bg-emerald-500/10 border border-emerald-500/30 hover:bg-emerald-500/20 text-emerald-400 rounded-lg transition">
                <CheckCircle size={12} /> Approve
              </button>
            )}
            {canSchedule && (
              <button id="news-schedule-btn" onClick={() => setShowScheduleDialog(true)}
                className="flex items-center gap-1.5 px-3 py-2 text-xs font-bold bg-cyan-500/10 border border-cyan-500/30 hover:bg-cyan-500/20 text-cyan-400 rounded-lg transition">
                <Calendar size={12} /> Schedule
              </button>
            )}
            {canPublish && (
              <button id="news-publish-btn" onClick={() => quickAction("publish")} disabled={actionLoading === "publish"}
                className="flex items-center gap-1.5 px-3 py-2 text-xs font-bold bg-green-500/10 border border-green-500/30 hover:bg-green-500/20 text-green-400 rounded-lg transition">
                {actionLoading === "publish" ? <Loader2 size={12} className="animate-spin" /> : <Eye size={12} />} Publish
              </button>
            )}
            {canUnpublish && (
              <button id="news-unpublish-btn" onClick={() => quickAction("unpublish")} disabled={actionLoading === "unpublish"}
                className="flex items-center gap-1.5 px-3 py-2 text-xs font-bold bg-yellow-500/10 border border-yellow-500/30 hover:bg-yellow-500/20 text-yellow-400 rounded-lg transition">
                {actionLoading === "unpublish" ? <Loader2 size={12} className="animate-spin" /> : <EyeOff size={12} />} Unpublish
              </button>
            )}
            {canReject && (
              <button id="news-reject-btn" onClick={() => setShowRejectDialog(true)}
                className="flex items-center gap-1.5 px-3 py-2 text-xs font-bold bg-red-500/10 border border-red-500/30 hover:bg-red-500/20 text-red-400 rounded-lg transition">
                <XCircle size={12} /> Reject
              </button>
            )}
            {canUnarchive && (
              <button id="news-restore-btn" onClick={() => quickAction("restore")} disabled={actionLoading === "restore"}
                className="flex items-center gap-1.5 px-3 py-2 text-xs font-bold bg-indigo-500/10 border border-indigo-500/30 hover:bg-indigo-500/20 text-indigo-400 rounded-lg transition">
                {actionLoading === "restore" ? <Loader2 size={12} className="animate-spin" /> : <RotateCcw size={12} />} Restore to Draft
              </button>
            )}
            {canArchive && (
              <button id="news-archive-btn" onClick={() => quickAction("archive")} disabled={actionLoading === "archive"}
                className="flex items-center gap-1.5 px-3 py-2 text-xs font-bold bg-slate-500/10 border border-slate-500/30 hover:bg-slate-500/20 text-slate-400 rounded-lg transition">
                {actionLoading === "archive" ? <Loader2 size={12} className="animate-spin" /> : <Archive size={12} />} Archive
              </button>
            )}
          </div>
        </div>
      </div>

      <div className="max-w-[1440px] mx-auto px-6 py-8">
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">

          {/* LEFT: Source panel */}
          <div className="space-y-5">
            <h2 className="text-base font-bold text-muted uppercase tracking-wider text-xs">Source Attribution</h2>

            <Section title="Original Source" icon={<Globe size={16} className="text-blue-400" />}>
              <div className="pt-4 space-y-4">
                {/* Source URL — always visible, always linked */}
                <div className="p-4 bg-blue-500/5 border border-blue-500/20 rounded-xl space-y-2">
                  <div className="text-[11px] font-semibold text-blue-400 uppercase tracking-wider">Source URL (Immutable)</div>
                  <a
                    id="news-review-source-url"
                    href={article.source_url}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="flex items-center gap-2 text-sm text-blue-400 hover:text-blue-300 break-all font-medium transition"
                  >
                    <ExternalLink size={14} className="shrink-0" />
                    {article.source_url}
                  </a>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <div className="text-[11px] font-semibold text-muted uppercase tracking-wider mb-1">Source Name</div>
                    <div className="text-sm font-semibold text-main">{article.source_name}</div>
                  </div>
                  <div>
                    <div className="text-[11px] font-semibold text-muted uppercase tracking-wider mb-1">Tier</div>
                    <div className="text-sm font-semibold text-main">{TIER_LABEL[article.source_tier] || article.source_tier}</div>
                  </div>
                  <div>
                    <div className="text-[11px] font-semibold text-muted uppercase tracking-wider mb-1">Published At</div>
                    <div className="text-sm text-main">
                      {article.published_at ? new Date(article.published_at).toLocaleString("en-IN") : "—"}
                    </div>
                  </div>
                  <div>
                    <div className="text-[11px] font-semibold text-muted uppercase tracking-wider mb-1">Category</div>
                    <div className="text-sm text-main">{article.category}</div>
                  </div>
                </div>
              </div>
            </Section>

            <Section title="Affected Entities" icon={<Train size={16} className="text-amber-400" />} defaultOpen={true}>
              <div className="pt-4 space-y-3">
                {(article.affected_trains?.length || 0) > 0 ? (
                  <div>
                    <div className="text-[11px] font-semibold text-muted uppercase tracking-wider mb-2">
                      Trains ({article.affected_trains.length})
                    </div>
                    <div className="flex flex-wrap gap-2">
                      {article.affected_trains.map((t, i) => (
                        <a
                          key={i}
                          href={`/live/${t}`}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="px-2.5 py-1 bg-amber-400/10 border border-amber-400/20 hover:bg-amber-400/20 text-amber-400 text-xs rounded-lg font-semibold inline-flex items-center gap-1 transition-colors"
                          title={`Inspect Train ${t} Live Status`}
                        >
                          <span>#{t}</span>
                          <ExternalLink size={10} className="opacity-70" />
                        </a>
                      ))}
                    </div>
                  </div>
                ) : <p className="text-sm text-muted pt-2">No trains affected.</p>}

                {(article.affected_stations?.length || 0) > 0 ? (
                  <div>
                    <div className="text-[11px] font-semibold text-muted uppercase tracking-wider mb-2">
                      Stations ({article.affected_stations.length})
                    </div>
                    <div className="flex flex-wrap gap-2">
                      {article.affected_stations.map((s, i) => (
                        <span key={i} className="px-2.5 py-1 bg-blue-400/10 border border-blue-400/20 text-blue-400 text-xs rounded-lg font-semibold">
                          {s}
                        </span>
                      ))}
                    </div>
                  </div>
                ) : <p className="text-sm text-muted">No stations affected.</p>}
              </div>
            </Section>

            {/* Audit History */}
            <Section title="Audit History" icon={<History size={16} className="text-slate-400" />} defaultOpen={false}>
              <div className="pt-4 space-y-2">
                {article.audit_history?.length === 0 ? (
                  <p className="text-sm text-muted">No audit events yet.</p>
                ) : (
                  article.audit_history?.map(entry => (
                    <div key={entry.id} className="flex items-start gap-3 py-3 border-b border-subtle last:border-0">
                      <div className="mt-0.5 w-2 h-2 rounded-full bg-primary/60 shrink-0" />
                      <div>
                        <div className="text-xs font-semibold text-main">
                          {entry.action.replace("NEWS_CMS_", "")}
                          <span className="text-muted font-normal ml-2">by {entry.admin_email}</span>
                        </div>
                        <div className="text-[10px] text-muted mt-0.5">
                          {entry.details?.previous_status} → {entry.details?.new_status}
                          {entry.details?.reason && <span className="ml-2 text-orange-400">· {entry.details.reason}</span>}
                        </div>
                        <div className="text-[10px] text-muted mt-0.5">
                          {new Date(entry.timestamp).toLocaleString("en-IN")}
                        </div>
                      </div>
                    </div>
                  ))
                )}
              </div>
            </Section>
          </div>

          {/* RIGHT: AI Draft editor */}
          <div className="space-y-5">
            <div className="flex items-center justify-between">
              <h2 className="text-base font-bold text-muted uppercase tracking-wider text-xs">AI Draft</h2>
              {hasDraftChanges && <span className="text-[10px] text-amber-400 font-bold">• UNSAVED CHANGES</span>}
            </div>

            <Section title="Content" icon={<FileText size={16} className="text-indigo-400" />}>
              <div className="pt-4 space-y-4">
                <EditableField id="draft-title" label="Title" value={edits.title || ""} onChange={v => updateEdit("title", v)} disabled={!canEdit} />
                <EditableField id="draft-summary" label="Summary" value={edits.summary || ""} onChange={v => updateEdit("summary", v)} multiline disabled={!canEdit} />
                <EditableField id="draft-takeaways" label="Key Takeaways (one per line)" value={edits.key_takeaways || ""} onChange={v => updateEdit("key_takeaways", v)} multiline disabled={!canEdit} />
                <div className="space-y-1.5">
                  <div className="flex items-center justify-between">
                    <label htmlFor="draft-passenger-advice" className="text-[11px] font-semibold text-muted uppercase tracking-wider">
                      Passenger Advice
                    </label>
                    <span className="text-[10px] text-muted font-normal">Actionable travel guidance</span>
                  </div>
                  <textarea
                    id="draft-passenger-advice"
                    value={edits.passenger_advice || ""}
                    onChange={e => updateEdit("passenger_advice", e.target.value)}
                    disabled={!canEdit}
                    rows={4}
                    placeholder="e.g. Passengers booked on cancelled trains are eligible for automatic full refunds. Alternate routes via..."
                    className="w-full bg-input border border-subtle rounded-lg px-3 py-2.5 text-sm text-main resize-none outline-none focus:border-primary/60 disabled:opacity-50 transition"
                  />
                  <p className="text-[10px] text-muted italic">
                    💡 <strong>Passenger Advice:</strong> Actionable guidance for passengers regarding cancellations, automatic refunds, route diversions, or alternative routes.
                  </p>
                </div>

                <div className="space-y-1.5">
                  <div className="flex items-center justify-between flex-wrap gap-2">
                    <div className="flex items-center gap-2">
                      <label htmlFor="draft-content" className="text-[11px] font-semibold text-muted uppercase tracking-wider">
                        Full Article Content (Markdown)
                      </label>
                      <span className={`text-[10px] font-mono px-2 py-0.5 rounded-full border ${
                        contentWordCount >= 250 && contentWordCount <= 450
                          ? "bg-emerald-500/10 text-emerald-400 border-emerald-500/30 font-semibold"
                          : contentWordCount > 450
                          ? "bg-blue-500/10 text-blue-400 border-blue-500/30"
                          : contentWordCount > 0
                          ? "bg-amber-500/10 text-amber-400 border-amber-500/30"
                          : "bg-muted/10 text-muted border-subtle"
                      }`}>
                        {contentWordCount} {contentWordCount === 1 ? "word" : "words"} · Target: 250–450 words
                      </span>
                    </div>

                    {/* Edit / Preview Tabs */}
                    <div className="flex items-center bg-input border border-subtle rounded-lg p-0.5 text-xs">
                      <button
                        type="button"
                        id="news-content-tab-edit"
                        onClick={() => setContentTab("edit")}
                        className={`px-2.5 py-1 rounded-md font-medium transition ${
                          contentTab === "edit"
                            ? "bg-primary text-white shadow-sm font-semibold"
                            : "text-muted hover:text-main"
                        }`}
                      >
                        Edit
                      </button>
                      <button
                        type="button"
                        id="news-content-tab-preview"
                        onClick={() => setContentTab("preview")}
                        className={`px-2.5 py-1 rounded-md font-medium transition flex items-center gap-1 ${
                          contentTab === "preview"
                            ? "bg-primary text-white shadow-sm font-semibold"
                            : "text-muted hover:text-main"
                        }`}
                      >
                        <Eye size={12} /> Preview
                      </button>
                    </div>
                  </div>

                  {contentTab === "edit" ? (
                    <textarea
                      id="draft-content"
                      value={edits.content || ""}
                      onChange={e => updateEdit("content", e.target.value)}
                      disabled={!canEdit}
                      rows={10}
                      placeholder="Write or edit article content using Markdown (headings ##, bullet lists, bold text)..."
                      className="w-full bg-input border border-subtle rounded-lg px-3 py-2.5 text-sm text-main font-mono text-xs resize-y outline-none focus:border-primary/60 disabled:opacity-50 transition"
                    />
                  ) : (
                    <div
                      id="news-content-preview-container"
                      className="w-full bg-card border border-subtle rounded-lg p-4 min-h-[220px] max-h-[480px] overflow-y-auto"
                    >
                      {(edits.content || "").trim() ? (
                        <SafeMarkdown content={edits.content} className="text-main" />
                      ) : (
                        <p className="text-xs text-muted italic">No content to preview.</p>
                      )}
                    </div>
                  )}

                  <p className="text-[10px] text-muted italic">
                    💡 <strong>Markdown Support:</strong> Use <code>## Heading</code>, <code>- bullet points</code>, <code>**bold text**</code>, and links. Structured for search engine crawlability and passenger clarity.
                  </p>
                </div>
              </div>
            </Section>

            <Section title="Frequently Asked Questions (FAQ)" icon={<HelpCircle size={16} className="text-amber-400" />} defaultOpen={true}>
              <div className="pt-4 space-y-4">
                <div className="flex items-center justify-between">
                  <span className="text-[11px] font-semibold text-muted uppercase tracking-wider">
                    FAQ Items ({Array.isArray(edits.faq) ? edits.faq.length : 0})
                  </span>
                  {canEdit && (
                    <button
                      type="button"
                      onClick={addFaq}
                      className="px-2.5 py-1 bg-amber-500/15 hover:bg-amber-500/25 text-amber-400 border border-amber-500/30 rounded-lg text-xs font-semibold inline-flex items-center gap-1 transition"
                    >
                      <Plus size={12} /> Add FAQ
                    </button>
                  )}
                </div>

                {(!edits.faq || edits.faq.length === 0) ? (
                  <p className="text-sm text-muted">No FAQs defined for this article.</p>
                ) : (
                  edits.faq.map((item: any, idx: number) => {
                    const isQuestionMissing = !item.question || !item.question.trim();
                    const isAnswerMissing = !item.answer || !item.answer.trim();
                    const isIncomplete = isQuestionMissing || isAnswerMissing;
                    return (
                      <div key={idx} className="p-3 bg-input border border-subtle rounded-xl space-y-2 relative">
                        <div className="flex items-center justify-between">
                          <span className="text-[11px] font-bold text-amber-400 font-mono">Q&amp;A #{idx + 1}</span>
                          {canEdit && (
                            <button
                              type="button"
                              onClick={() => removeFaq(idx)}
                              className="text-muted hover:text-red-400 p-1 transition"
                              title="Remove FAQ"
                            >
                              <Trash2 size={13} />
                            </button>
                          )}
                        </div>
                        <input
                          placeholder="Question (e.g. Will passengers receive an automatic refund?)"
                          value={item.question || ""}
                          onChange={e => updateFaq(idx, "question", e.target.value)}
                          disabled={!canEdit}
                          className={`w-full bg-card border rounded-lg px-3 py-2 text-xs text-main outline-none focus:border-amber-400/60 disabled:opacity-50 transition ${
                            isQuestionMissing ? "border-amber-500/40" : "border-subtle"
                          }`}
                        />
                        <textarea
                          placeholder="Answer (e.g. Yes, 100% refund is automatically credited by IRCTC...)"
                          value={item.answer || ""}
                          onChange={e => updateFaq(idx, "answer", e.target.value)}
                          disabled={!canEdit}
                          rows={2}
                          className={`w-full bg-card border rounded-lg px-3 py-2 text-xs text-main resize-none outline-none focus:border-amber-400/60 disabled:opacity-50 transition ${
                            isAnswerMissing ? "border-amber-500/40" : "border-subtle"
                          }`}
                        />
                        {isIncomplete && (
                          <div className="flex items-center gap-1.5 text-[10px] text-amber-400 bg-amber-500/5 px-2.5 py-1 rounded-md border border-amber-500/20">
                            <AlertTriangle size={11} className="shrink-0" />
                            <span>
                              {isQuestionMissing && isAnswerMissing
                                ? "Both question and answer are empty. This item will not be saved."
                                : isQuestionMissing
                                ? "Question is missing. Provide a question or remove this item."
                                : "Answer is missing. Provide an answer or remove this item."}
                            </span>
                          </div>
                        )}
                      </div>
                    );
                  })
                )}
              </div>
            </Section>

            <Section title="SEO & Search Engine Readiness" icon={<Globe size={16} className="text-emerald-400" />} defaultOpen={true}>
              <div className="pt-4 space-y-5">
                {/* Plain-English SEO helper banner */}
                <div className="p-3.5 bg-emerald-500/5 border border-emerald-500/20 rounded-xl space-y-1 text-xs">
                  <div className="flex items-center gap-2 font-bold text-emerald-400">
                    <Sparkles size={14} />
                    <span>Non-Technical Admin Guide: Search Engine Optimization</span>
                  </div>
                  <p className="text-muted leading-relaxed text-[11px]">
                    Google and search engines use these fields to understand and rank railway notices.
                    Keep descriptions helpful, factual, and focused on passenger travel queries.
                  </p>
                </div>

                {/* SEO Title Field with explanation */}
                <div className="space-y-1.5">
                  <div className="flex items-center justify-between">
                    <label htmlFor="draft-seo-title" className="text-[11px] font-semibold text-muted uppercase tracking-wider flex items-center gap-1.5">
                      <span>SEO Title</span>
                      <span className="text-[10px] text-muted lowercase font-normal">({(edits.seo_title || "").length} / 60 chars)</span>
                    </label>
                    <span className="text-[10px] text-emerald-400 font-mono font-medium">Google search mein article ka main title</span>
                  </div>
                  <input
                    id="draft-seo-title"
                    value={edits.seo_title || ""}
                    onChange={e => updateEdit("seo_title", e.target.value)}
                    disabled={!canEdit}
                    placeholder="e.g. Mumbai to Delhi Special Train Announced: Check Schedule & Tatkal Booking"
                    className="w-full bg-input border border-subtle rounded-lg px-3 py-2.5 text-sm text-main outline-none focus:border-emerald-500/60 disabled:opacity-50 transition"
                  />
                  <p className="text-[10px] text-muted italic">
                    💡 <strong>SEO Title:</strong> Google search results mein sabse upar clickable blue link ke roop mein dikhta hai.
                  </p>
                </div>

                {/* Meta Description Field with explanation */}
                <div className="space-y-1.5">
                  <div className="flex items-center justify-between">
                    <label htmlFor="draft-meta-description" className="text-[11px] font-semibold text-muted uppercase tracking-wider flex items-center gap-1.5">
                      <span>Meta Description</span>
                      <span className="text-[10px] text-muted lowercase font-normal">({(edits.meta_description || "").length} / 160 chars)</span>
                    </label>
                    <span className="text-[10px] text-emerald-400 font-mono font-medium">Search result snippet text</span>
                  </div>
                  <textarea
                    id="draft-meta-description"
                    value={edits.meta_description || ""}
                    onChange={e => updateEdit("meta_description", e.target.value)}
                    disabled={!canEdit}
                    rows={3}
                    placeholder="e.g. Indian Railways announces new Mumbai-Delhi special trains with tatkal quota seats. Read timings, station stops, and booking advice."
                    className="w-full bg-input border border-subtle rounded-lg px-3 py-2.5 text-sm text-main resize-none outline-none focus:border-emerald-500/60 disabled:opacity-50 transition"
                  />
                  <p className="text-[10px] text-muted italic">
                    💡 <strong>Meta Description:</strong> Google search snippet ke neeche 2 lines ki short summary hoti hai jisse passenger click karein.
                  </p>
                </div>

                {/* Slug Field with explanation */}
                <div className="space-y-1.5">
                  <div className="flex items-center justify-between">
                    <label htmlFor="draft-slug" className="text-[11px] font-semibold text-muted uppercase tracking-wider">URL Slug</label>
                    <span className="text-[10px] text-emerald-400 font-mono font-medium">Article ka clean web link</span>
                  </div>
                  <input
                    id="draft-slug"
                    value={edits.slug || ""}
                    onChange={e => updateEdit("slug", e.target.value)}
                    disabled={!canEdit}
                    placeholder="e.g. irctc-mumbai-delhi-special-trains-schedule"
                    className="w-full bg-input border border-subtle rounded-lg px-3 py-2.5 text-sm text-main font-mono text-xs outline-none focus:border-emerald-500/60 disabled:opacity-50 transition"
                  />
                  <p className="text-[10px] text-muted italic">
                    💡 <strong>Slug:</strong> Article ka unique web address. Hyphens (-) se words separate karein, special characters na dalein.
                  </p>
                </div>

                {/* Canonical URL Preview */}
                <div className="p-3 bg-input border border-subtle rounded-xl space-y-1">
                  <div className="flex items-center justify-between text-[11px]">
                    <span className="font-semibold text-muted uppercase tracking-wider flex items-center gap-1.5">
                      <Link2 size={12} className="text-primary" /> Canonical URL Preview
                    </span>
                    <span className="text-[10px] text-muted font-mono">search engine primary index</span>
                  </div>
                  <div className="text-xs font-mono text-primary truncate">
                    https://www.trayago.in/news/{edits.slug || article.slug || article.id}
                  </div>
                </div>

                {/* Structured Schema & Search Capabilities Grid */}
                <div className="pt-2 border-t border-subtle space-y-2">
                  <div className="text-[11px] font-semibold text-muted uppercase tracking-wider">
                    Automated Schema &amp; Indexing Capabilities
                  </div>
                  <div className="grid grid-cols-2 gap-2 text-xs">
                    <div className="p-2.5 bg-input border border-subtle rounded-lg flex items-center gap-2">
                      <CheckCircle2 size={14} className="text-emerald-400 shrink-0" />
                      <div>
                        <div className="font-bold text-main text-[11px]">NewsArticle Schema</div>
                        <div className="text-[10px] text-muted">JSON-LD for Google Top Stories</div>
                      </div>
                    </div>
                    <div className="p-2.5 bg-input border border-subtle rounded-lg flex items-center gap-2">
                      <CheckCircle2 size={14} className="text-emerald-400 shrink-0" />
                      <div>
                        <div className="font-bold text-main text-[11px]">Breadcrumb Schema</div>
                        <div className="text-[10px] text-muted">Home &gt; News &gt; {article.category}</div>
                      </div>
                    </div>
                    <div className="p-2.5 bg-input border border-subtle rounded-lg flex items-center gap-2">
                      {article.faq && article.faq.length > 0 ? (
                        <CheckCircle2 size={14} className="text-emerald-400 shrink-0" />
                      ) : (
                        <Info size={14} className="text-muted shrink-0" />
                      )}
                      <div>
                        <div className="font-bold text-main text-[11px]">FAQ Schema</div>
                        <div className="text-[10px] text-muted">
                          {article.faq && article.faq.length > 0 ? `${article.faq.length} Q&As active` : "Auto-formatted if FAQ exists"}
                        </div>
                      </div>
                    </div>
                    <div className="p-2.5 bg-input border border-subtle rounded-lg flex items-center gap-2">
                      <CheckCircle2 size={14} className="text-emerald-400 shrink-0" />
                      <div>
                        <div className="font-bold text-main text-[11px]">Sitemap Inclusion</div>
                        <div className="text-[10px] text-muted">Auto-indexed on publish</div>
                      </div>
                    </div>
                    <div className="p-2.5 bg-input border border-subtle rounded-lg flex items-center gap-2">
                      <CheckCircle2 size={14} className="text-emerald-400 shrink-0" />
                      <div>
                        <div className="font-bold text-main text-[11px]">Source Attribution</div>
                        <div className="text-[10px] text-muted">Immutable publisher citation</div>
                      </div>
                    </div>
                    <div className="p-2.5 bg-input border border-subtle rounded-lg flex items-center gap-2">
                      <CheckCircle2 size={14} className="text-emerald-400 shrink-0" />
                      <div>
                        <div className="font-bold text-main text-[11px]">Related Articles</div>
                        <div className="text-[10px] text-muted">Deterministic train/station matches</div>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </Section>

            {/* Pre-Publishing Readiness & Verification Checklist */}
            {(() => {
              const checkSource = Boolean(article.source_name && article.source_url);
              const contentVal = typeof edits.content === "string" ? edits.content : (article.content || "");
              const hasMeaningfulContent = Boolean(contentVal && contentVal.trim().length > 50);
              const checkContent = Boolean((edits.title || article.title) && (edits.summary || article.summary) && hasMeaningfulContent);
              const checkClaims = ["APPROVED", "PUBLISHED", "SCHEDULED"].includes(article.status) || allApproveChecksPass;
              const checkSeoTitle = Boolean(edits.seo_title || article.seo_title || edits.title || article.title);
              const checkMetaDesc = Boolean(edits.meta_description || article.meta_description || edits.summary || article.summary);
              const checkSlug = Boolean((edits.slug || article.slug)?.trim());
              const checkEntities = (article.affected_trains?.length || 0) > 0 || (article.affected_stations?.length || 0) > 0 || true;
              const checkAttribution = Boolean(article.source_url);

              const allChecksPass = checkSource && checkContent && checkClaims && checkSeoTitle && checkMetaDesc && checkSlug && checkEntities && checkAttribution;
              const isReady = allChecksPass && ["APPROVED", "SCHEDULED"].includes(article.status);

              return (
                <Section title="Pre-Publishing &amp; Quality Checklist" icon={<ListChecks size={16} className="text-indigo-400" />} defaultOpen={true}>
                  <div className="pt-4 space-y-4">
                    {/* Status header badge */}
                    <div className={`flex items-center justify-between p-4 rounded-xl border ${
                      isReady ? "bg-emerald-500/10 border-emerald-500/30 text-emerald-400" : "bg-orange-500/10 border-orange-500/30 text-orange-400"
                    }`}>
                      <div className="flex items-center gap-2.5 font-black text-sm">
                        {isReady ? <CheckCircle2 size={18} /> : <AlertTriangle size={18} />}
                        <span>{isReady ? "READY TO PUBLISH" : "REVIEW REQUIRED"}</span>
                      </div>
                      <span className="text-xs font-mono font-medium">
                        {isReady ? "All governance & SEO criteria met" : "Complete human review & approval"}
                      </span>
                    </div>

                    {/* 8-point checklist items */}
                    <div className="space-y-2 text-xs">
                      {[
                        { label: "Source verified & validated against official publishers", pass: checkSource },
                        { label: "Content reviewed for passenger clarity & accuracy (title, summary, full content >50 chars)", pass: checkContent },
                        { label: "No unsupported claims or speculative AI hallucinations", pass: checkClaims },
                        { label: "SEO title present and optimized for Google search", pass: checkSeoTitle },
                        { label: "Meta description present for rich snippet previews", pass: checkMetaDesc },
                        { label: "Valid URL slug without prohibited characters", pass: checkSlug },
                        { label: "Affected railway entities (trains & stations) valid", pass: checkEntities },
                        { label: "Source attribution & publisher citation preserved", pass: checkAttribution },
                      ].map((item, idx) => (
                        <div key={idx} className="flex items-center justify-between p-2.5 bg-input border border-subtle rounded-lg">
                          <div className="flex items-center gap-2 text-main">
                            {item.pass ? (
                              <CheckCircle2 size={14} className="text-emerald-400 shrink-0" />
                            ) : (
                              <XCircle size={14} className="text-orange-400 shrink-0" />
                            )}
                            <span className={item.pass ? "text-main" : "text-muted"}>{item.label}</span>
                          </div>
                          <span className={`text-[10px] font-bold font-mono ${item.pass ? "text-emerald-400" : "text-orange-400"}`}>
                            {item.pass ? "PASS" : "PENDING"}
                          </span>
                        </div>
                      ))}
                    </div>
                  </div>
                </Section>
              );
            })()}

            {/* Confidence & Validation */}
            <Section title="AI Confidence &amp; Validation" icon={<Shield size={16} className="text-purple-400" />} defaultOpen={true}>
              <div className="pt-4 space-y-3">
                {article.ai_confidence ? (
                  <div className={`flex items-center gap-2.5 p-3 rounded-xl border ${CONFIDENCE_STYLE[article.ai_confidence] || "border-subtle"}`}>
                    <Shield size={14} />
                    <span className="text-sm font-bold">AI Confidence: {article.ai_confidence}</span>
                  </div>
                ) : (
                  <div className="p-3 bg-muted/10 border border-subtle rounded-xl text-muted text-sm">
                    AI confidence not recorded.
                  </div>
                )}
                {article.ai_confidence === "LOW" && (
                  <div className="flex items-start gap-2 p-3 bg-red-500/5 border border-red-500/20 rounded-xl">
                    <AlertTriangle size={14} className="text-red-400 mt-0.5 shrink-0" />
                    <p className="text-xs text-red-400">
                      Low confidence articles require careful fact-checking before approval.
                      Verify every claim against the source URL.
                    </p>
                  </div>
                )}
                {article.rejection_reason && (
                  <div className="p-3 bg-red-500/5 border border-red-500/20 rounded-xl">
                    <div className="text-[11px] font-semibold text-red-400 mb-1">Rejection Reason</div>
                    <div className="text-sm text-main">{article.rejection_reason}</div>
                  </div>
                )}
                {article.scheduled_at && (
                  <div className="flex items-center gap-2 p-3 bg-cyan-500/5 border border-cyan-500/20 rounded-xl text-cyan-400 text-sm">
                    <Calendar size={14} />
                    Scheduled: {new Date(article.scheduled_at).toLocaleString("en-IN")}
                  </div>
                )}
              </div>
            </Section>
          </div>
        </div>
      </div>

      {/* ═══ Approve Dialog ═══════════════════════════════════════════════════ */}
      {showApproveDialog && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 backdrop-blur-sm p-4">
          <div className="bg-card border border-subtle rounded-2xl w-full max-w-md shadow-2xl">
            <div className="p-6 border-b border-subtle flex items-center gap-2.5">
              <CheckCircle size={18} className="text-emerald-400" />
              <h3 className="font-bold text-main text-base">Pre-Approval Checklist</h3>
            </div>
            <div className="p-6 space-y-3">
              <p className="text-xs text-muted mb-4">
                Complete all checks before approving. Your identity and this action will be audited.
              </p>
              {[
                { key: "sourceVerified",    label: "I have visited and verified the source URL" },
                { key: "confidenceReviewed",label: "I have reviewed the AI confidence level" },
                { key: "contentAccurate",   label: "The draft content is factually accurate" },
                { key: "entitiesValid",     label: "Affected trains and stations are correct" },
              ].map(check => (
                <label key={check.key} className={`flex items-center gap-3 p-3 rounded-xl border cursor-pointer transition ${
                  (approveChecks as any)[check.key] ? "border-emerald-500/40 bg-emerald-500/5" : "border-subtle hover:border-emerald-500/20"
                }`}>
                  <input
                    id={`approve-check-${check.key}`}
                    type="checkbox"
                    checked={(approveChecks as any)[check.key]}
                    onChange={e => setApproveChecks(prev => ({ ...prev, [check.key]: e.target.checked }))}
                    className="w-4 h-4 accent-emerald-500"
                  />
                  <span className="text-sm text-main">{check.label}</span>
                </label>
              ))}
              <div className={`mt-4 p-3 rounded-xl border text-xs ${allApproveChecksPass ? "border-emerald-500/30 bg-emerald-500/5 text-emerald-400" : "border-subtle text-muted"}`}>
                {allApproveChecksPass ? (
                  <span className="font-semibold">✓ Attestation ready: "I verified the source and approve this article."</span>
                ) : (
                  "Complete all checks to enable approval."
                )}
              </div>
            </div>
            <div className="p-4 border-t border-subtle flex gap-3 justify-end">
              <button id="approve-dialog-cancel" onClick={() => setShowApproveDialog(false)} className="px-4 py-2 text-sm text-muted hover:text-main border border-subtle rounded-lg transition">Cancel</button>
              <button
                id="approve-dialog-confirm"
                onClick={handleApprove}
                disabled={!allApproveChecksPass || actionLoading === "approve"}
                className="flex items-center gap-2 px-4 py-2 text-sm font-bold bg-emerald-500 hover:bg-emerald-600 text-white rounded-lg transition disabled:opacity-40"
              >
                {actionLoading === "approve" ? <Loader2 size={14} className="animate-spin" /> : <CheckCircle size={14} />}
                Confirm Approval
              </button>
            </div>
          </div>
        </div>
      )}

      {/* ═══ Reject Dialog ════════════════════════════════════════════════════ */}
      {showRejectDialog && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 backdrop-blur-sm p-4">
          <div className="bg-card border border-subtle rounded-2xl w-full max-w-md shadow-2xl">
            <div className="p-6 border-b border-subtle flex items-center gap-2.5">
              <XCircle size={18} className="text-red-400" />
              <h3 className="font-bold text-main text-base">Reject Article</h3>
            </div>
            <div className="p-6 space-y-4">
              <div className="space-y-1.5">
                <label className="text-[11px] font-semibold text-muted uppercase tracking-wider">Rejection Reason</label>
                <select
                  id="reject-reason"
                  value={rejectReason}
                  onChange={e => setRejectReason(e.target.value)}
                  className="w-full bg-input border border-subtle text-sm text-main rounded-lg px-3 py-2.5 outline-none"
                >
                  {REJECTION_REASONS.map(r => <option key={r.value} value={r.value}>{r.label}</option>)}
                </select>
              </div>
              <div className="space-y-1.5">
                <label className="text-[11px] font-semibold text-muted uppercase tracking-wider">Note (optional)</label>
                <textarea
                  id="reject-note"
                  value={rejectNote}
                  onChange={e => setRejectNote(e.target.value)}
                  rows={3}
                  placeholder="Add context for this rejection..."
                  className="w-full bg-input border border-subtle text-sm text-main rounded-lg px-3 py-2.5 resize-none outline-none"
                />
              </div>
            </div>
            <div className="p-4 border-t border-subtle flex gap-3 justify-end">
              <button id="reject-dialog-cancel" onClick={() => setShowRejectDialog(false)} className="px-4 py-2 text-sm text-muted hover:text-main border border-subtle rounded-lg transition">Cancel</button>
              <button
                id="reject-dialog-confirm"
                onClick={handleReject}
                disabled={actionLoading === "reject"}
                className="flex items-center gap-2 px-4 py-2 text-sm font-bold bg-red-500 hover:bg-red-600 text-white rounded-lg transition"
              >
                {actionLoading === "reject" ? <Loader2 size={14} className="animate-spin" /> : <XCircle size={14} />}
                Confirm Rejection
              </button>
            </div>
          </div>
        </div>
      )}

      {/* ═══ Schedule Dialog ══════════════════════════════════════════════════ */}
      {showScheduleDialog && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 backdrop-blur-sm p-4">
          <div className="bg-card border border-subtle rounded-2xl w-full max-w-md shadow-2xl">
            <div className="p-6 border-b border-subtle flex items-center gap-2.5">
              <Calendar size={18} className="text-cyan-400" />
              <h3 className="font-bold text-main text-base">Schedule Publishing</h3>
            </div>
            <div className="p-6 space-y-4">
              <p className="text-xs text-muted">Select a future date and time. Article will remain in SCHEDULED state until published.</p>
              <div className="space-y-1.5">
                <label className="text-[11px] font-semibold text-muted uppercase tracking-wider">Date &amp; Time</label>
                <input
                  id="schedule-datetime"
                  type="datetime-local"
                  value={scheduleAt}
                  onChange={e => setScheduleAt(e.target.value)}
                  min={new Date(Date.now() + 60000).toISOString().slice(0, 16)}
                  className="w-full bg-input border border-subtle text-sm text-main rounded-lg px-3 py-2.5 outline-none"
                />
              </div>
              {scheduleAt && (
                <div className="p-3 bg-cyan-500/5 border border-cyan-500/20 rounded-xl text-xs text-cyan-400">
                  Will publish: {new Date(scheduleAt).toLocaleString("en-IN", { timeZoneName: "short" })}
                </div>
              )}
            </div>
            <div className="p-4 border-t border-subtle flex gap-3 justify-end">
              <button id="schedule-dialog-cancel" onClick={() => setShowScheduleDialog(false)} className="px-4 py-2 text-sm text-muted hover:text-main border border-subtle rounded-lg transition">Cancel</button>
              <button
                id="schedule-dialog-confirm"
                onClick={handleSchedule}
                disabled={!scheduleAt || actionLoading === "schedule"}
                className="flex items-center gap-2 px-4 py-2 text-sm font-bold bg-cyan-500 hover:bg-cyan-600 text-white rounded-lg transition disabled:opacity-40"
              >
                {actionLoading === "schedule" ? <Loader2 size={14} className="animate-spin" /> : <Calendar size={14} />}
                Confirm Schedule
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
