import React, { ReactNode } from "react";
import Link from "next/link";

interface SafeMarkdownProps {
  content: string | null | undefined;
  className?: string;
}

export interface MarkdownBlock {
  type: "heading" | "p" | "ul" | "ol" | "blockquote" | "code" | "hr" | "table";
  level?: number;
  text?: string;
  items?: string[];
  lang?: string;
  headers?: string[];
  alignments?: ("left" | "center" | "right")[];
  rows?: string[][];
}

export function isSafeUrl(url: string): boolean {
  if (!url || typeof url !== "string") return false;
  const trimmed = url.trim();
  if (trimmed.startsWith("/") || trimmed.startsWith("#")) return true;
  try {
    const parsed = new URL(trimmed);
    return parsed.protocol === "http:" || parsed.protocol === "https:" || parsed.protocol === "mailto:";
  } catch {
    return false;
  }
}

export function parseInline(text: string): ReactNode[] {
  if (!text) return [];

  // Match links, bold-italic, bold, code, strike, asterisk italic, and bounded underscore italic
  const pattern = /(\[[^\]]+\]\([^)]+\)|\*\*\*[^*]+\*\*\*|\*\*[^*]+\*\*|__[^_]+__|`[^`]+`|~~[^~]+~~|\*[^*\s][^*]*\*|(?<=\s|^)_[^_\s][^_]*_(?=\s|$|[.,;:!?]))/g;

  const parts = text.split(pattern);
  const nodes: ReactNode[] = [];

  for (let i = 0; i < parts.length; i++) {
    const part = parts[i];
    if (!part) continue;

    // Link: [text](url)
    const linkMatch = part.match(/^\[(.*?)\]\((.*?)\)$/);
    if (linkMatch) {
      const linkText = linkMatch[1];
      const linkUrl = linkMatch[2].trim();
      if (isSafeUrl(linkUrl)) {
        const isExternal = linkUrl.startsWith("http:") || linkUrl.startsWith("https:");
        nodes.push(
          <a
            key={i}
            href={linkUrl}
            target={isExternal ? "_blank" : undefined}
            rel={isExternal ? "noopener noreferrer" : undefined}
            className="text-blue-600 dark:text-blue-400 font-medium underline underline-offset-2 hover:text-blue-700 dark:hover:text-blue-300 transition-colors"
          >
            {parseInline(linkText)}
          </a>
        );
      } else {
        nodes.push(<span key={i}>{linkText}</span>);
      }
      continue;
    }

    // Bold-Italic: ***text***
    if (part.startsWith("***") && part.endsWith("***") && part.length > 6) {
      nodes.push(
        <strong key={i} className="font-bold text-main">
          <em className="italic">{part.slice(3, -3)}</em>
        </strong>
      );
      continue;
    }

    // Bold: **text** or __text__
    if (
      (part.startsWith("**") && part.endsWith("**") && part.length > 4) ||
      (part.startsWith("__") && part.endsWith("__") && part.length > 4)
    ) {
      nodes.push(
        <strong key={i} className="font-bold text-main">
          {parseInline(part.slice(2, -2))}
        </strong>
      );
      continue;
    }

    // Inline Code: `text`
    if (part.startsWith("`") && part.endsWith("`") && part.length > 2) {
      nodes.push(
        <code
          key={i}
          className="bg-subtle/60 dark:bg-slate-800/80 px-1.5 py-0.5 rounded text-xs sm:text-sm font-mono text-blue-600 dark:text-blue-400 border border-subtle"
        >
          {part.slice(1, -1)}
        </code>
      );
      continue;
    }

    // Strikethrough: ~~text~~
    if (part.startsWith("~~") && part.endsWith("~~") && part.length > 4) {
      nodes.push(
        <del key={i} className="line-through text-muted">
          {parseInline(part.slice(2, -2))}
        </del>
      );
      continue;
    }

    // Italic: *text* or _text_
    if (
      (part.startsWith("*") && part.endsWith("*") && part.length > 2) ||
      (part.startsWith("_") && part.endsWith("_") && part.length > 2)
    ) {
      nodes.push(
        <em key={i} className="italic">
          {part.slice(1, -1)}
        </em>
      );
      continue;
    }

    // Plain text (React safely renders string as escaped text node)
    nodes.push(part);
  }

  return nodes;
}

export function parseBlocks(markdown: string): MarkdownBlock[] {
  if (!markdown || typeof markdown !== "string") return [];
  const lines = markdown.replace(/\r\n/g, "\n").split("\n");
  const blocks: MarkdownBlock[] = [];
  let i = 0;

  while (i < lines.length) {
    const line = lines[i];

    // Fenced Code Block
    if (line.trim().startsWith("```")) {
      const codeLines: string[] = [];
      const lang = line.trim().slice(3).trim();
      i++;
      while (i < lines.length && !lines[i].trim().startsWith("```")) {
        codeLines.push(lines[i]);
        i++;
      }
      if (i < lines.length) i++; // skip closing ```
      blocks.push({ type: "code", lang, text: codeLines.join("\n") });
      continue;
    }

    // Empty lines
    if (line.trim() === "") {
      i++;
      continue;
    }

    // Horizontal Rule
    if (/^(?:---|\*\*\*|___)\s*$/.test(line.trim())) {
      blocks.push({ type: "hr" });
      i++;
      continue;
    }

    // Headings: # to ######
    const headingMatch = line.match(/^(#{1,6})\s+(.*)$/);
    if (headingMatch) {
      blocks.push({
        type: "heading",
        level: headingMatch[1].length,
        text: headingMatch[2].trim(),
      });
      i++;
      continue;
    }

    // Blockquote: > ...
    if (line.trim().startsWith(">")) {
      const quoteLines: string[] = [];
      while (i < lines.length && lines[i].trim().startsWith(">")) {
        quoteLines.push(lines[i].replace(/^>\s?/, ""));
        i++;
      }
      blocks.push({ type: "blockquote", text: quoteLines.join("\n") });
      continue;
    }

    // Unordered List: - or *
    if (/^[-*]\s+/.test(line.trim())) {
      const items: string[] = [];
      while (i < lines.length && /^[-*]\s+/.test(lines[i].trim())) {
        items.push(lines[i].trim().replace(/^[-*]\s+/, ""));
        i++;
      }
      blocks.push({ type: "ul", items });
      continue;
    }

    // Ordered List: 1. 2. etc
    if (/^\d+\.\s+/.test(line.trim())) {
      const items: string[] = [];
      while (i < lines.length && /^\d+\.\s+/.test(lines[i].trim())) {
        items.push(lines[i].trim().replace(/^\d+\.\s+/, ""));
        i++;
      }
      blocks.push({ type: "ol", items });
      continue;
    }

    // Markdown Table: header line with pipes, followed by delimiter line with |-+:|
    if (
      line.trim().startsWith("|") &&
      i + 1 < lines.length &&
      /^\|?(\s*:?-+:?\s*\|)+\s*:?-+:?\s*\|?$/.test(lines[i + 1].trim())
    ) {
      const splitCells = (l: string) => {
        let s = l.trim();
        if (s.startsWith("|")) s = s.slice(1);
        if (s.endsWith("|")) s = s.slice(0, -1);
        return s.split("|").map((c) => c.trim());
      };

      const headers = splitCells(lines[i]);
      const sepCells = splitCells(lines[i + 1]);
      const alignments: ("left" | "center" | "right")[] = sepCells.map((c) => {
        const trimmed = c.trim();
        if (trimmed.startsWith(":") && trimmed.endsWith(":")) return "center";
        if (trimmed.endsWith(":")) return "right";
        return "left";
      });

      i += 2; // skip header and delimiter lines
      const rows: string[][] = [];

      while (i < lines.length && lines[i].trim().startsWith("|")) {
        // Stop if blank line or other block
        if (lines[i].trim() === "") break;
        rows.push(splitCells(lines[i]));
        i++;
      }

      blocks.push({
        type: "table",
        headers,
        alignments,
        rows,
      });
      continue;
    }

    // Paragraph: collect lines until blank line or another block
    const pLines: string[] = [];
    while (
      i < lines.length &&
      lines[i].trim() !== "" &&
      !lines[i].trim().startsWith("```") &&
      !/^(?:---|\*\*\*|___)\s*$/.test(lines[i].trim()) &&
      !lines[i].match(/^#{1,6}\s+/) &&
      !lines[i].trim().startsWith(">") &&
      !/^[-*]\s+/.test(lines[i].trim()) &&
      !/^\d+\.\s+/.test(lines[i].trim()) &&
      !(lines[i].trim().startsWith("|") && i + 1 < lines.length && /^\|?(\s*:?-+:?\s*\|)+\s*:?-+:?\s*\|?$/.test(lines[i + 1].trim()))
    ) {
      pLines.push(lines[i]);
      i++;
    }
    if (pLines.length > 0) {
      blocks.push({ type: "p", text: pLines.join(" ") });
    }
  }

  return blocks;
}

export default function SafeMarkdown({ content, className = "" }: SafeMarkdownProps) {
  if (!content || typeof content !== "string" || content.trim().length === 0) {
    return null;
  }

  const blocks = parseBlocks(content);
  if (blocks.length === 0) {
    return null;
  }

  return (
    <div className={`article-content space-y-4 text-main ${className}`}>
      {blocks.map((block, idx) => {
        switch (block.type) {
          case "heading": {
            const headingText = block.text || "";
            // Preserve single h1 semantic hierarchy: # and ## map to h2, ### to h3, >=4 to h4
            if (block.level === 1 || block.level === 2) {
              return (
                <h2
                  key={idx}
                  className="text-xl sm:text-2xl font-bold text-main tracking-tight pt-4 pb-1 border-b border-subtle/50 first:pt-0"
                >
                  {parseInline(headingText)}
                </h2>
              );
            }
            if (block.level === 3) {
              return (
                <h3 key={idx} className="text-lg sm:text-xl font-bold text-main tracking-tight pt-2">
                  {parseInline(headingText)}
                </h3>
              );
            }
            return (
              <h4 key={idx} className="text-base sm:text-lg font-semibold text-main pt-1">
                {parseInline(headingText)}
              </h4>
            );
          }
          case "p": {
            return (
              <p key={idx} className="text-sm sm:text-base text-main leading-relaxed">
                {parseInline(block.text || "")}
              </p>
            );
          }
          case "ul": {
            return (
              <ul key={idx} className="list-disc pl-5 sm:pl-6 space-y-1.5 text-sm sm:text-base text-main my-3">
                {(block.items || []).map((item, itemIdx) => (
                  <li key={itemIdx} className="leading-relaxed">
                    {parseInline(item)}
                  </li>
                ))}
              </ul>
            );
          }
          case "ol": {
            return (
              <ol key={idx} className="list-decimal pl-5 sm:pl-6 space-y-1.5 text-sm sm:text-base text-main my-3">
                {(block.items || []).map((item, itemIdx) => (
                  <li key={itemIdx} className="leading-relaxed">
                    {parseInline(item)}
                  </li>
                ))}
              </ol>
            );
          }
          case "blockquote": {
            return (
              <blockquote
                key={idx}
                className="border-l-4 border-blue-500/40 bg-blue-500/5 dark:bg-blue-950/20 pl-4 py-2.5 my-4 rounded-r-xl italic text-main text-sm sm:text-base"
              >
                {parseInline(block.text || "")}
              </blockquote>
            );
          }
          case "code": {
            return (
              <pre
                key={idx}
                className="bg-card border border-subtle rounded-xl p-4 overflow-x-auto text-xs sm:text-sm font-mono text-main my-4 shadow-sm"
              >
                <code>{block.text}</code>
              </pre>
            );
          }
          case "table": {
            return (
              <div key={idx} className="my-6 overflow-x-auto rounded-2xl border border-subtle bg-card/60 shadow-sm">
                <table className="w-full text-left text-xs sm:text-sm border-collapse min-w-[500px]">
                  {block.headers && block.headers.length > 0 && (
                    <thead className="bg-subtle/80 border-b border-subtle">
                      <tr>
                        {block.headers.map((h, hIdx) => {
                          const align = block.alignments?.[hIdx] || "left";
                          return (
                            <th
                              key={hIdx}
                              className={`px-3.5 py-3 font-extrabold text-main uppercase tracking-wider text-[11px] ${
                                align === "center" ? "text-center" : align === "right" ? "text-right" : "text-left"
                              }`}
                            >
                              {parseInline(h)}
                            </th>
                          );
                        })}
                      </tr>
                    </thead>
                  )}
                  <tbody className="divide-y divide-subtle/50">
                    {(block.rows || []).map((row, rIdx) => (
                      <tr
                        key={rIdx}
                        className="hover:bg-subtle/30 transition-colors duration-150 odd:bg-transparent even:bg-subtle/10"
                      >
                        {row.map((cell, cIdx) => {
                          const align = block.alignments?.[cIdx] || "left";
                          const trimmed = cell.trim();
                          const isTrainNo = /^\d{5}$/.test(trimmed);
                          const isOperational = /^(operational|running|active)$/i.test(trimmed);
                          const isSpecialCategory = /^(special|vande bharat)$/i.test(trimmed);

                          return (
                            <td
                              key={cIdx}
                              className={`px-3.5 py-3 text-main font-medium ${
                                align === "center" ? "text-center" : align === "right" ? "text-right" : "text-left"
                              }`}
                            >
                              {isTrainNo ? (
                                <Link
                                  href={`/live/${trimmed}`}
                                  className="inline-flex items-center gap-1 font-mono font-bold text-blue-600 dark:text-blue-400 bg-blue-500/10 px-2 py-0.5 rounded border border-blue-500/20 hover:underline"
                                >
                                  {trimmed}
                                </Link>
                              ) : isOperational ? (
                                <span className="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-[11px] font-bold bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border border-emerald-500/20">
                                  ● {trimmed}
                                </span>
                              ) : isSpecialCategory ? (
                                <span className="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-md text-[11px] font-bold bg-purple-500/10 text-purple-600 dark:text-purple-400 border border-purple-500/20">
                                  {trimmed}
                                </span>
                              ) : (
                                parseInline(cell)
                              )}
                            </td>
                          );
                        })}
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            );
          }
          case "hr": {
            return <hr key={idx} className="border-subtle my-6" />;
          }
          default:
            return null;
        }
      })}
    </div>
  );
}
