/**
 * PHASE_4C981 — Bug Fix: Admin Access Denied on token expiry.
 *
 * Raw `fetch()` in admin pages bypasses AxiosInterceptor.tsx, which owns
 * the silent 401 → token-refresh → retry cycle. This wrapper replicates
 * that exact lifecycle for admin `fetch` calls.
 *
 * Behaviour mirrors AxiosInterceptor.tsx exactly:
 *  - 401 + error === 'invalid_token_version' → clear session, redirect /login
 *  - Any other 401 (first attempt only) → POST /auth/refresh → retry once
 *  - All other responses → returned as-is
 */

import { API_BASE } from '@/lib/api';

/**
 * Build the Authorization header from localStorage.
 * Returns an empty object when running server-side or when no token exists.
 */
function buildBearerHeader(): Record<string, string> {
  if (typeof window === 'undefined') return {};
  try {
    const token = localStorage.getItem('accessToken');
    return token ? { Authorization: `Bearer ${token}` } : {};
  } catch {
    return {};
  }
}

/**
 * Drop the stored session and hard-redirect to login.
 * Matches the AxiosInterceptor redirect path exactly.
 */
function clearSessionAndRedirect(): void {
  try {
    localStorage.removeItem('user');
    localStorage.removeItem('accessToken');
    localStorage.removeItem('refreshToken');
  } catch {
    // Storage may be disabled — proceed to redirect regardless
  }
  if (typeof window !== 'undefined' && !window.location.pathname.startsWith('/login')) {
    window.location.href = '/login';
  }
}

/**
 * Fetch wrapper that transparently handles 401 token expiry
 * by attempting a silent refresh and retrying the original request once.
 *
 * @param input  Same as `fetch` first argument (URL or Request)
 * @param init   Same as `fetch` RequestInit, merged with auth headers
 */
export async function fetchWithAuth(
  input: RequestInfo | URL,
  init: RequestInit = {}
): Promise<Response> {
  // Merge caller-supplied headers with the current auth token
  const headersWithAuth: Record<string, string> = {
    ...(init.headers as Record<string, string> | undefined ?? {}),
    ...buildBearerHeader(),
  };

  const firstResponse = await fetch(input, {
    ...init,
    headers: headersWithAuth,
  });

  // Fast-path: not a 401 — return immediately
  if (firstResponse.status !== 401) {
    return firstResponse;
  }

  // Parse the 401 body to identify the error type
  let errorBody: { error?: string } = {};
  try {
    // Clone so the body is still readable by the caller if needed
    errorBody = await firstResponse.clone().json();
  } catch {
    // Malformed body — treat as a retryable 401
  }

  // Attempt silent refresh (mirrors AxiosInterceptor lines 80-86)
  try {
    let storedRefreshToken: string | null = null;
    try {
      storedRefreshToken = localStorage.getItem('refreshToken');
    } catch {}

    const refreshRes = await fetch(`${API_BASE}/auth/refresh`, {
      method: 'POST',
      credentials: 'include',
      headers: {
        'Content-Type': 'application/json',
        ...(storedRefreshToken ? { Authorization: `Bearer ${storedRefreshToken}` } : {})
      },
      body: JSON.stringify(storedRefreshToken ? { refreshToken: storedRefreshToken } : {})
    });

    if (!refreshRes.ok) {
      if (refreshRes.status === 401) {
        try {
          localStorage.removeItem('accessToken');
          localStorage.removeItem('refreshToken');
        } catch {}
      }
      return firstResponse;
    }

    const refreshData: { success?: boolean; accessToken?: string; refreshToken?: string } = await refreshRes.json();

    if (!refreshData.success || !refreshData.accessToken) {
      return firstResponse;
    }

    // Persist new token
    try {
      localStorage.setItem('accessToken', refreshData.accessToken);
      if (refreshData.refreshToken) {
        localStorage.setItem('refreshToken', refreshData.refreshToken);
      }
    } catch {
      // Storage disabled — token cannot be persisted but we can still retry
    }

    // Retry the original request with the new token
    const retryHeaders: Record<string, string> = {
      ...(init.headers as Record<string, string> | undefined ?? {}),
      Authorization: `Bearer ${refreshData.accessToken}`,
    };

    return fetch(input, { ...init, headers: retryHeaders });
  } catch {
    // Network failure during refresh — do not redirect, surface 401 to caller
    return firstResponse;
  }
}
